-- GENERATED by `wfj generate` from data/gossip/gossip-76.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["7601222d451454b0"] = { "Esatto, ehm, <ragazzo/ragazza>, tutto il materiale bellico viene trasportato a ⟦Silithus=Silitus⟧ e l'ultima parte dovrebbe arrivare entro un giorno. Dopodiché non ci resterà che aspettare e vedere chi si farà avanti per ricomporre lo Scettro delle Sabbie Mutevoli e suonare il gong sull'Altare dello Scarabeo. Solo quando ciò accadrà la guerra comincerà ad aprire le porte di ⟦Ahn'Qiraj=Ahn'qiraj⟧.", "." },
  ["76070f6a3e008350"] = { "Questo sembra un compito degno del nuovo re!", "." },
  ["760de24a806a24c4"] = { "La resa dei conti è giunta per te, debole!", "." },
  ["7616774c3f5dc90d"] = { "Anche tu sei <un/una> <ragazzo/ragazza> materialista, eh? Beh, se sei <ossessionato/ossessionata> dai tuoi preziosi oggetti, probabilmente vorrai custodirli alla banca di Darnassus, al centro della nostra città.", "." },
  ["7616bfd62e5ad914"] = { "Qui nelle ⟦Badlands=Maleterre⟧ può fare davvero caldo. Ma almeno è un caldo secco.", "." },
  ["761b7ac8aab4a819"] = { "Non merito tali lodi, signore della guerra Goretooth.", "." },
  ["761cc108833060a9"] = { "Sindaco Ello! I nostri esploratori del cimitero tornano con notizie inquietanti...", "." },
  ["7622aaa1e8801ab3"] = { "Non ho ancora capito cosa sia, ma c'è qualcosa di strano nelle sorgenti termali...", "." },
  ["76275e6e28340fd7"] = { "A Malyfous, presumo.", "." },
  ["762aaa2512d06c82"] = { "Torta, amore mio! Finalmente eccomi di nuovo da te.", "." },
  ["76324ecc60c80653"] = { "Non dovresti essere in giro a salvare il mondo?", "." },
  ["763359a5ee661ce4"] = { "È giunto il momento di dimostrare quanto vali come gregario, {name}. Prendi questo segnalatore e piantalo proprio al centro del Cimitero di Nevealta. Difendilo finché non arriva la mia flotta.\n\n<Mulverick fa il saluto militare.>", "." },
  ["763885ec7f132d35"] = { "Ladri in edificio su anello esterno di ⟦Rogues' Quarter=Quartiere dei Ladri⟧.", "." },
  ["763a9d0b0f062248"] = { "Sì. L'ho fatto.", "." },
  ["7641890a51267957"] = { "Era avvolto dagli incubi, Malfurion. Cosa sta succedendo nel Sogno? Cosa potrebbe causare simili atrocità?", "." },
  ["7644ee093b8a046e"] = { "Voglio quegli stivali! Nessuno tocchi quel cadavere!", "." },
  ["764ea632ed899683"] = { "Torna a trovarmi.", "." },
  ["765721a504c56256"] = { "%s sembra sul punto di vomitare!", "." },
  ["765b240adbb2dd1d"] = { "E una volta, al campo, ho preso un pesce più grosso di me!!", "." },
  ["765fe603ac858790"] = { "Credo che i rumori venissero da qui. Meglio andare a controllare.", "." },
  ["7663ec646ebd244d"] = { "La battaglia è finita, e la gente del ⟦Darrowshire=Borgo di Darrow⟧ è salva.\n\nÈ salva, {name}, grazie a te. Sei davvero <un/una> <eroe/eroina> del ⟦Darrowshire=Borgo di Darrow⟧.", "." },
  ["7664152bfd02b784"] = { "È fatta...", "." },
  ["76699afbd14e4e74"] = { "%s si stiracchia e si lascia andare a un grosso sbadiglio.", "." },
  ["766c2a406794cd51"] = { "Sì, lo so, sembra che abbiamo già tutti i lingotti di mithril che ci servono per la guerra. Ma sai, qui intorno c'è ancora un sacco di gente a cui il tuo aiuto farebbe comodo proprio adesso. Grazie, amico.", "." },
  ["7672666598ae19db"] = { "Vuoi dire che da qui non senti l'odore del fumo delle forge naniche? Beh, se vuoi imparare la forgiatura devi cercare Therum Deepforge. Si trova nel Distretto dei Nani, appena a nord della Cathedral Square.", "." },
  ["767e24f8cbdb6116"] = { "Rivendare! Vengo a prenderti!", "." },
  ["768fc89186c7ad10"] = { "Bene, bene. Continuate così e questo ponte sarà finito in un attimo.", "." },
  ["7691190654cab07f"] = { "Ehi! Sei qui per una commissione di Tirth? Fossi in te, starei il più lontano possibile da lui! Ha il cervello marinato dall'alcol, ma la sua magia è potente come sempre!", "." },
  ["7697733aca7176b0"] = { "Il Cimitero dei Lupi Bianchi appartiene all'⟦Alliance=Alleanza⟧.", "." },
  ["7699bbf7fec1fbde"] = { "È fatta! Il Signore del Ghiaccio è arrivato! Inchinatevi alla potenza dell'⟦Horde=Orda⟧, stolti!", "." },
  ["769be6d58705ec95"] = { "Miei signori! Vengo da voi!", "." },
  ["769e8da36a7335bd"] = { "Appena trecento anni fa, un nano sconsiderato di nome Thaurissan evocò il padrone dal suo regno di fuoco. Il suo ritorno in questo misero mondo devastò le terre circostanti e creò questo Nucleo vulcanico. Da allora il possente Ragnaros dorme sotto questa montagna.", "." },
  ["76a077a1be077349"] = { "Salve di nuovo, {name}. Pensavi che ti avrei scordato?\n\nSapevo che non l'avresti pensato. Sei <un/una> {class} <sveglio/sveglia>, che riconosce una persona dalla memoria perfetta quando la vede.", "." },
  ["76a3e8a43e0738fe"] = { "Arrr, compari! Ho un po' di tesoro in più che regalerò all'⟦Gurubashi Arena=Arena dei Gurubashi⟧! Per prenderlo non dovete far altro che aprire lo scrigno che lascerò sul pavimento dell'arena!", "." },
  ["76a82426ff3d8116"] = { "Questo andrà benissimo. Ora, al lavoro!", "." },
  ["76aa88be4bbd5cd1"] = { "Sono Krathok, sovrintendente di questi artigiani.", "." },
  ["76aab025725ecad1"] = { "Per i Blu!", "." },
  ["76af7fc20ebbdbd5"] = { "Di cosa hai bisogno da me, <figlio/figlia> di Zephras?", "." },
  ["76b2e40ba48ad0ea"] = { "Gli atti di proprietà sono miei, fratello! Presto ti avrò tolto di mezzo una volta per tutte!", "." },
  ["76b6808ca06b80f5"] = { "Se vogliamo conquistarci un posto in questo mondo, lo faremo con lo studio e con la volontà di ignorare i nostri istinti umani che svaniscono.", "." },
  ["76c63b3a18a37701"] = { "In questi tempi difficili, una semplice donazione di stoffa può fare molto per aiutare chi è meno fortunato di noi. Con la stoffa si fanno indumenti e bende, entrambi importanti per lo sforzo bellico!\n\nSe vuoi donare pezzi di stoffa agli orchi di Orgrimmar, li accetterò volentieri e mi assicurerò che tu riceva il giusto riconoscimento.\n\nPer l'⟦Horde=Orda⟧!", "." },
  ["76d3309a6f9518e0"] = { "È ora di affrontare la vostra prova finale, giovani guerrieri! Preparatevi al combattimento più duro finora.", "." },
  ["76d6d8705519f965"] = { "Per i Selvalercia sei solo un moscerino! Muori!", "." },
  ["76d79b9c6dee4a33"] = { "Salve, {class}. Se sei qui, allora saprai che ⟦Silverpine=Pinargento⟧ brulica di nostri nemici. Per sopravvivere, i Reietti devono ricacciarli indietro!", "." },
  ["76dcf9595036598a"] = { "Ecco gli ordini, {name}. Portali in fretta al maestro di guerra Garrick!", "." },
  ["76dfa605246d1849"] = { "A dire il vero preferisco i rimedi tradizionali... sanguisughe, vermi, seghe per ossa... cose del genere. Beh, de gustibus. Troverai Faruza, che da noi insegna erbalismo, davanti all'ingresso, vicino alle stalle di Brill.", "." },
  ["76f46cdab011fd67"] = { "E così ha inizio...", "." },
})
